INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9501, 'តើអ្វីទៅជានិយមន័យនៃរង្វង់?', 'g8-687a9cd926.svg', '["ជាផ្ទៃរាបដែលព័ទ្ធជុំវិញដោយជ្រុងបួនស្មើគ្នា", "ជាខ្សែកោងរាបបិទដែលគ្រប់ចំណុចនៅលើខ្សែកោងនោះមានចម្ងាយស្មើគ្នាពីចំណុចនឹងមួយ (ផ្ចិត)", "ជាពហុកោណដែលមានជ្រុងច្រើនរាប់មិនអស់", "ជាខ្សែកោងចំហដែលមានប្រវែងកំណត់"]', 1, NULL, 1, 'mcq', 'រង្វង់គឺជាខ្សែកោងរាបបិទដែលគ្រប់ចំណុចលើខ្សែកោងមានចម្ងាយស្មើគ្នាពីចំណុចនឹងមួយហៅថាផ្ចិត', 'រង្វង់', 'easy', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9502, 'តាមបីចំណុចផ្សេងគ្នាដែលមិនស្ថិតនៅលើបន្ទាត់តែមួយ តើគេអាចគូសបានរង្វង់ចំនួនប៉ុន្មានកាត់តាមចំណុចទាំងបីនោះ?', NULL, '["២", "៣", "ច្រើនរាប់មិនអស់", "១ គត់"]', 3, NULL, 1, 'mcq', 'តាម ៣ ចំណុចមិនរត់ត្រង់ជួរគ្នា គេអាចគូសបានរង្វង់តែមួយគត់ (រង្វង់ចារឹកក្រៅត្រីកោណ)', 'រង្វង់', 'easy', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9503, 'តើអង្កត់ធ្នូណាដែលវែងជាងគេបំផុតនៅក្នុងរង្វង់មួយ?', NULL, '["បន្ទាត់ប៉ះ", "កាំ", "ធ្នូ", "អង្កត់ផ្ចិត"]', 3, NULL, 1, 'mcq', 'អង្កត់ផ្ចិតគឺជាអង្កត់ធ្នូដែលវែងជាងគេនៅក្នុងរង្វង់មួយ ព្រោះវាឆ្លងកាត់ផ្ចិតរង្វង់', 'រង្វង់', 'easy', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9504, 'រង្វង់មួយមានកាំ \(r = 7\ \text{cm}\)។ គណនាប្រវែងអង្កត់ផ្ចិត \(d\) នៃរង្វង់។', NULL, '["\\(49\\ \\text{cm}\\)", "\\(14\\ \\text{cm}\\)", "\\(21\\ \\text{cm}\\)", "\\(7\\ \\text{cm}\\)"]', 1, NULL, 1, 'mcq', '\(d = 2r = 2 \times 7 = 14\ \text{cm}\)', 'រង្វង់', 'easy', 1, '8', 'រង្វង់', NULL, 0);
