INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9505, 'មុំមួយដែលមានកំពូលស្ថិតនៅចំផ្ចិតនៃរង្វង់ ហើយជ្រុងទាំងពីរកាត់រង្វង់ ហៅថាមុំអ្វី?', 'g8-455a9ef3f6.svg', '["មុំចារឹកក្នុង", "មុំផ្ចិត", "មុំក្រៅ", "មុំជាប់"]', 1, NULL, 1, 'mcq', 'មុំដែលមានកំពូលត្រង់ផ្ចិតនៃរង្វង់ ហៅថា មុំផ្ចិត (Central Angle)', 'រង្វង់', 'easy', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9506, 'បើមុំផ្ចិត \(ngle AOB = 75^\circ\) នោះរង្វាស់ដឺក្រេនៃធ្នូស្កាត់ \(\overset{rown}{AB}\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(105^\\circ\\)", "\\(75^\\circ\\)", "\\(37.5^\\circ\\)", "\\(150^\\circ\\)"]', 1, NULL, 1, 'mcq', 'រង្វាស់ដឺក្រេនៃធ្នូស្កាត់ ស្មើនឹងរង្វាស់នៃមុំផ្ចិតដែលស្កាត់ធ្នូនោះ ៖ \(\overset{rown}{AB} = ngle AOB = 75^\circ\)', 'រង្វង់', 'easy', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9507, 'តើរូបមន្តគណនាបរិមាត្ររង្វង់ដែលមានកាំ \(r\) ណាត្រឹមត្រូវ?', NULL, '["\\(P = \\pi d^2\\)", "\\(P = 2\\pi r\\)", "\\(P = \\pi r^2\\)", "\\(P = 2\\pi r^2\\)"]', 1, NULL, 1, 'mcq', 'បរិមាត្ររង្វង់ ៖ \(P = 2\pi r = \pi d\)', 'រង្វង់', 'easy', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9508, 'តើចំណុចណាជាផ្ចិតឆ្លុះនៃរង្វង់មួយ?', NULL, '["គ្មានផ្ចិតឆ្លុះទេ", "ចុងនៃអង្កត់ផ្ចិត", "ចំណុចណាមួយនៅលើរង្វង់", "ផ្ចិតនៃរង្វង់"]', 3, NULL, 1, 'mcq', 'ផ្ចិតនៃរង្វង់ គឺជាផ្ចិតឆ្លុះនៃរង្វង់នោះ', 'រង្វង់', 'easy', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9509, 'អង្កត់ផ្ចិតពីរកែងគ្នាក្នុងរង្វង់មួយ បែងចែករង្វង់ជាធ្នូប៉ុនគ្នាចំនួន ៤។ តើធ្នូនីមួយៗ (កាដ្រង់) មានរង្វាស់ប៉ុន្មានដឺក្រេ?', NULL, '["\\(180^\\circ\\)", "\\(45^\\circ\\)", "\\(360^\\circ\\)", "\\(90^\\circ\\)"]', 3, NULL, 1, 'mcq', '\(\dfrac{360^\circ}{4} = 90^\circ\)', 'រង្វង់', 'easy', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9510, 'បើបីចំណុចផ្សេងគ្នាស្ថិតនៅលើបន្ទាត់តែមួយ (រត់ត្រង់ជួរគ្នា) តើគេអាចគូសបានរង្វង់កាត់តាមចំណុចទាំងបីបានឬទេ?', NULL, '["បានច្រើនរាប់មិនអស់", "បាន ២", "បាន ១ គត់", "មិនអាចទេ"]', 3, NULL, 1, 'mcq', 'បើបីចំណុចរត់ត្រង់ជួរគ្នា គេមិនអាចគូសរង្វង់កាត់តាមចំណុចទាំងបីនោះបានឡើយ', 'រង្វង់', 'easy', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9511, 'រង្វង់មួយមានកាំ \(r = 15\ \text{cm}\)។ គណនាប្រវែងធ្នូដែលស្កាត់ដោយមុំផ្ចិត \(80^\circ\) (យក \(\pi pprox 3.14\))។', NULL, '["\\(94.2\\ \\text{cm}\\)", "\\(41.86\\ \\text{cm}\\)", "\\(20.93\\ \\text{cm}\\)", "\\(10.47\\ \\text{cm}\\)"]', 2, NULL, 2, 'mcq', '\(L = \dfrac{2\pi r \times 80^\circ}{360^\circ} = \dfrac{2 \times 3.14 \times 15 \times 80}{360} pprox 20.93\ \text{cm}\)', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9512, 'ក្នុងរង្វង់ \(\mathcal{C}(O, r)\) ត្រីកោណ \(OAB\) មាន \(ngle OAB = 25^\circ\)។ គណនារង្វាស់ធ្នូ \(\overset{rown}{AB}\)។', NULL, '["\\(155^\\circ\\)", "\\(65^\\circ\\)", "\\(50^\\circ\\)", "\\(130^\\circ\\)"]', 3, NULL, 2, 'mcq', '\(OA = OB = r \Rightarrow ngle OBA = 25^\circ \Rightarrow ngle AOB = 180^\circ - 2(25^\circ) = 130^\circ \Rightarrow \overset{rown}{AB} = 130^\circ\)', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g8-77edf0b3c0.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9513, 'អង្កត់ផ្ចិតមួយកែងនឹងអង្កត់ធ្នូ \(AB\) ត្រង់ \(H\)។ បើ \(AB = 16\ \text{cm}\) គណនាប្រវែង \(AH\)។', 'g8-77edf0b3c0.svg', '["\\(12\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\)", "\\(4\\ \\text{cm}\\)", "\\(16\\ \\text{cm}\\)"]', 1, NULL, 2, 'mcq', 'អង្កត់ផ្ចិតកែងនឹងអង្កត់ធ្នូ ចែកអង្កត់ធ្នូនោះជាពីរស្មើគ្នា ៖ \(AH = \dfrac{16}{2} = 8\ \text{cm}\)', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9514, 'រង្វង់ផ្ចិត \(O\) មានកាំ \(r = 10\ \text{cm}\)។ អង្កត់ធ្នូ \(AB\) នៅចម្ងាយ \(6\ \text{cm}\) ពីផ្ចិត \(O\)។ គណនាប្រវែងអង្កត់ធ្នូ \(AB\)។', NULL, '["\\(12\\ \\text{cm}\\)", "\\(20\\ \\text{cm}\\)", "\\(16\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\)"]', 2, NULL, 2, 'mcq', '\(AH = \sqrt{10^2 - 6^2} = 8\ \text{cm} \Rightarrow AB = 2 \times 8 = 16\ \text{cm}\)', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g8-5679fc37ca.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9515, 'ក្នុងរង្វង់ផ្ចិត \(O\) អង្កត់ធ្នូ \(AB\) និង \(CD\) នៅចម្ងាយស្មើគ្នាពីផ្ចិត \(O\) (\(OQ = OR\))។ បើ \(AB = 18\ \text{cm}\) គណនា \(CD\)។', 'g8-5679fc37ca.svg', '["\\(12\\ \\text{cm}\\)", "\\(18\\ \\text{cm}\\)", "\\(36\\ \\text{cm}\\)", "\\(9\\ \\text{cm}\\)"]', 1, NULL, 2, 'mcq', 'អង្កត់ធ្នូដែលនៅស្មើចម្ងាយពីផ្ចិត គឺជាអង្កត់ធ្នូប៉ុនគ្នា ៖ \(CD = AB = 18\ \text{cm}\)', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9516, 'ក្នុងរង្វង់ផ្ចិត \(O\) អង្កត់ធ្នូពីរស្របគ្នា \(AB \parallel CD\)។ តើសេចក្តីសន្និដ្ឋានណាត្រឹមត្រូវ?', NULL, '["\\(\\overset{\frown}{AB} = \\overset{\frown}{CD}\\)", "\\(\\overset{\frown}{AD} = \\overset{\frown}{BC}\\)", "\\(\\overset{\frown}{AC} = \\overset{\frown}{BD}\\)", "\\(AB = CD\\)"]', 2, NULL, 2, 'mcq', 'អង្កត់ធ្នូពីរស្របគ្នាក្នុងរង្វង់ ស្កាត់បានធ្នូពីរនៅចន្លោះនោះប៉ុនគ្នា ៖ \(\overset{rown}{AC} = \overset{rown}{BD}\)', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9517, 'បន្ទាត់ \((d)\) ប៉ះរង្វង់ \(\mathcal{C}(O, r)\) ត្រង់ចំណុច \(A\)។ តើមុំរវាងបន្ទាត់ប៉ះ \((d)\) និងកាំ \(OA\) ស្មើនឹងប៉ុន្មានដឺក្រេ?', NULL, '["\\(180^\\circ\\)", "\\(90^\\circ\\)", "\\(60^\\circ\\)", "\\(45^\\circ\\)"]', 1, NULL, 2, 'mcq', 'បន្ទាត់ប៉ះរង្វង់កែងនឹងកាំត្រង់ចំណុចប៉ះ ៖ \((d) \perp OA \Rightarrow 90^\circ\)', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9518, 'ពីចំណុច \(P\) នៅក្រៅរង្វង់ គេគូសបន្ទាត់ប៉ះពីរ \(PA\) និង \(PB\) ទៅនឹងរង្វង់ផ្ចិត \(O\) (ត្រង់ \(A\) និង \(B\))។ បើ \(PA = 12\ \text{cm}\) គណនា \(PB\)។', NULL, '["\\(6\\ \\text{cm}\\)", "\\(24\\ \\text{cm}\\)", "\\(15\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)"]', 3, NULL, 2, 'mcq', 'អង្កត់ប៉ះទាំងពីរគូសចេញពីចំណុចតែមួយនៅក្រៅរង្វង់មានប្រវែងស្មើគ្នា ៖ \(PB = PA = 12\ \text{cm}\)', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9519, 'ត្រីកោណសម័ង្ស \(ABC\) មួយចារឹកក្នុងរង្វង់ផ្ចិត \(O\)។ គណនារង្វាស់នៃធ្នូនីមួយៗ \(\overset{rown}{AB}, \overset{rown}{BC}, \overset{rown}{CA}\)។', NULL, '["\\(60^\\circ\\)", "\\(180^\\circ\\)", "\\(120^\\circ\\)", "\\(90^\\circ\\)"]', 2, NULL, 2, 'mcq', '\(\dfrac{360^\circ}{3} = 120^\circ\)', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9520, 'ការេ \(ABCD\) មួយចារឹកក្នុងរង្វង់ផ្ចិត \(O\)។ គណនារង្វាស់ដឺក្រេនៃធ្នូនីមួយៗ \(\overset{rown}{AB}\)។', NULL, '["\\(60^\\circ\\)", "\\(45^\\circ\\)", "\\(90^\\circ\\)", "\\(120^\\circ\\)"]', 2, NULL, 2, 'mcq', '\(\dfrac{360^\circ}{4} = 90^\circ\)', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9521, 'គេឱ្យរង្វង់ពីរ \(\mathcal{C}(A, 3\ \text{cm})\) និង \(\mathcal{C}(B, 5\ \text{cm})\) ដោយ \(AB = 8\ \text{cm}\)។ តើរង្វង់ទាំងពីរនេះមានទីតាំងធៀបគ្នាយ៉ាងដូចម្តេច?', NULL, '["នៅដាច់ពីគ្នា", "កាត់គ្នាត្រង់ ២ ចំណុច", "ប៉ះគ្នាក្នុង", "ប៉ះគ្នាក្រៅ"]', 3, NULL, 2, 'mcq', '\(d = r_1 + r_2 = 3 + 5 = 8\ \text{cm}\) ដូចនេះរង្វង់ទាំងពីរប៉ះគ្នាក្រៅ', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9522, 'រង្វង់ពីរ \(\mathcal{C}(A, 4\ \text{cm})\) និង \(\mathcal{C}(B, 5\ \text{cm})\) មានចម្ងាយផ្ចិត \(AB = 6\ \text{cm}\)។ តើរង្វង់ទាំងពីរនេះមានទីតាំងធៀបគ្នាយ៉ាងដូចម្តេច?', NULL, '["ប៉ះគ្នាក្នុង", "ប៉ះគ្នាក្រៅ", "នៅដាច់ពីគ្នា", "កាត់គ្នាត្រង់ ២ ចំណុច"]', 3, NULL, 2, 'mcq', '\(|r_1 - r_2| < d < r_1 + r_2\) (\(1 < 6 < 9\)) នាំឱ្យរង្វង់ទាំងពីរកាត់គ្នាត្រង់ ២ ចំណុច', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9523, 'មុំផ្ចិតលយមួយមានរង្វាស់ \(110^\circ\)។ គណនារង្វាស់នៃមុំផ្ចិតឆកត្រូវគ្នា។', NULL, '["\\(200^\\circ\\)", "\\(180^\\circ\\)", "\\(70^\\circ\\)", "\\(250^\\circ\\)"]', 3, NULL, 2, 'mcq', '\(360^\circ - 110^\circ = 250^\circ\)', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9524, 'ក្នុងរង្វង់ផ្ចិត \(O\) អង្កត់ធ្នូពីរនៅស្មើចម្ងាយពីផ្ចិត មានកន្សោម \(AB = 3x + 5\) និង \(CD = 5x - 7\)។ គណនា \(x\)។', NULL, '["\\(x = 8\\)", "\\(x = 5\\)", "\\(x = 4\\)", "\\(x = 6\\)"]', 3, NULL, 2, 'mcq', '\(3x + 5 = 5x - 7 \Rightarrow 2x = 12 \Rightarrow x = 6\)', 'រង្វង់', 'medium', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9525, 'ពីចំណុច \(P\) គេគូសបន្ទាត់ប៉ះ \(PT\) ទៅនឹងរង្វង់ \(\mathcal{C}(O, 6\ \text{cm})\) ត្រង់ \(T\)។ បើ \(OP = 10\ \text{cm}\) គណនាប្រវែងបន្ទាត់ប៉ះ \(PT\)។', NULL, '["\\(8\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)", "\\(4\\ \\text{cm}\\)", "\\(16\\ \\text{cm}\\)"]', 0, NULL, 3, 'mcq', '\(PT = \sqrt{OP^2 - OT^2} = \sqrt{10^2 - 6^2} = \sqrt{64} = 8\ \text{cm}\)', 'រង្វង់', 'hard', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9526, 'រង្វង់មួយមានអង្កត់ធ្នូ \(AB = 24\ \text{cm}\) និងចម្ងាយពីផ្ចិតទៅអង្កត់ធ្នូនោះគឺ \(5\ \text{cm}\)។ គណនាកាំ \(r\) នៃរង្វង់។', NULL, '["\\(15\\ \\text{cm}\\)", "\\(13\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)", "\\(17\\ \\text{cm}\\)"]', 1, NULL, 3, 'mcq', '\(AH = 12\ \text{cm} \Rightarrow r = \sqrt{12^2 + 5^2} = \sqrt{144 + 25} = 13\ \text{cm}\)', 'រង្វង់', 'hard', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9527, 'រង្វង់មួយមានកាំ \(r = 10\ \text{cm}\)។ អង្កត់ធ្នូស្របគ្នាពីរ \(AB = 16\ \text{cm}\) និង \(CD = 12\ \text{cm}\) ស្ថិតនៅសងខាងនៃផ្ចិត \(O\)។ គណនាចម្ងាយរវាងអង្កត់ធ្នូទាំងពីរ។', NULL, '["\\(12\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)", "\\(16\\ \\text{cm}\\)", "\\(14\\ \\text{cm}\\)"]', 3, NULL, 3, 'mcq', '\(d_1 = \sqrt{10^2 - 8^2} = 6\ \text{cm}\), \(d_2 = \sqrt{10^2 - 6^2} = 8\ \text{cm} \Rightarrow d = 6 + 8 = 14\ \text{cm}\)', 'រង្វង់', 'hard', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9528, 'រង្វង់ពីរប៉ុនគ្នាមានកាំ \(r = 10\ \text{cm}\) កាត់គ្នាត្រង់ \(A\) និង \(B\)។ ចម្ងាយរវាងផ្ចិតទាំងពីរគឺ \(O_1 O_2 = 12\ \text{cm}\)។ គណនាប្រវែងអង្កត់ធ្នូរួម \(AB\)។', NULL, '["\\(16\\ \\text{cm}\\)", "\\(20\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\)"]', 0, NULL, 3, 'mcq', 'ចំណុចប្រសព្វមេដ្យាទ័រ ៖ \(O_1 H = 6\ \text{cm} \Rightarrow AH = \sqrt{10^2 - 6^2} = 8\ \text{cm} \Rightarrow AB = 16\ \text{cm}\)', 'រង្វង់', 'hard', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9529, 'ចម្រៀករង្វង់មួយមានកាំ \(r = 6\ \text{cm}\) និងមុំផ្ចិត \(60^\circ\)។ គណនាបរិមាត្រនៃចម្រៀករង្វង់នោះ (យក \(\pi pprox 3.14\))។', NULL, '["\\(12.28\\ \\text{cm}\\)", "\\(18.28\\ \\text{cm}\\)", "\\(24.28\\ \\text{cm}\\)", "\\(6.28\\ \\text{cm}\\)"]', 1, NULL, 3, 'mcq', 'ប្រវែងធ្នូ ៖ \(L = \dfrac{2 \times 3.14 \times 6 \times 60}{360} = 6.28\ \text{cm}\)។ បរិមាត្រចម្រៀក ៖ \(P = L + 2r = 6.28 + 12 = 18.28\ \text{cm}\)', 'រង្វង់', 'hard', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9530, 'ត្រីកោណកែងមួយមានជ្រុងមុំកែង \(6\ \text{cm}\) និង \(8\ \text{cm}\)។ គណនាកាំនៃរង្វង់ចារឹកក្រៅត្រីកោណកែងនោះ។', NULL, '["\\(5\\ \\text{cm}\\)", "\\(4\\ \\text{cm}\\)", "\\(7\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)"]', 0, NULL, 3, 'mcq', 'អ៊ីប៉ូតេនុសជាអង្កត់ផ្ចិតនៃរង្វង់ចារឹកក្រៅ ៖ \(c = \sqrt{6^2 + 8^2} = 10\ \text{cm} \Rightarrow R = \dfrac{10}{2} = 5\ \text{cm}\)', 'រង្វង់', 'hard', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9531, 'ក្នុងរង្វង់ \(\mathcal{C}(O, r)\) អង្កត់ធ្នូ \(AB\) មានប្រវែងស្មើនឹងកាំ \(r\) (\(AB = r\))។ គណនារង្វាស់ដឺក្រេនៃធ្នូតូច \(\overset{rown}{AB}\)។', NULL, '["\\(60^\\circ\\)", "\\(90^\\circ\\)", "\\(120^\\circ\\)", "\\(45^\\circ\\)"]', 0, NULL, 3, 'mcq', 'ត្រីកោណ \(OAB\) មាន \(OA = OB = AB = r\) ជាត្រីកោណសម័ង្ស នាំឱ្យ \(ngle AOB = 60^\circ \Rightarrow \overset{rown}{AB} = 60^\circ\)', 'រង្វង់', 'hard', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9532, 'កង់កង់មួយមានអង្កត់ផ្ចិត \(70\ \text{cm}\)។ តើកង់នោះវិលបានប៉ុន្មានជុំដើម្បីធ្វើដំណើរបានចម្ងាយ \(220\ \text{m}\) (យក \(\pi pprox \dfrac{22}{7}\))?', NULL, '["\\(150\\ \\text{ជុំ}\\)", "\\(100\\ \\text{ជុំ}\\)", "\\(200\\ \\text{ជុំ}\\)", "\\(50\\ \\text{ជុំ}\\)"]', 1, NULL, 3, 'mcq', 'បរិមាត្រកង់ ៖ \(P = \pi d = \dfrac{22}{7} \times 0.7\ \text{m} = 2.2\ \text{m} \Rightarrow N = \dfrac{220}{2.2} = 100\ \text{ជុំ}\)', 'រង្វង់', 'pisa', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9533, 'ទ្រនិចនាទីនៃនាឡិកាជញ្ជាំងមួយមានប្រវែង \(14\ \text{cm}\)។ គណនាចម្ងាយដែលចុងទ្រនិចនាទីចរបានក្នុងរយៈពេល \(45\ \text{នាទី}\) (យក \(\pi pprox \dfrac{22}{7}\))។', NULL, '["\\(66\\ \\text{cm}\\)", "\\(132\\ \\text{cm}\\)", "\\(44\\ \\text{cm}\\)", "\\(88\\ \\text{cm}\\)"]', 0, NULL, 3, 'mcq', '\(45\ \text{នាទី} = \dfrac{3}{4}\) ជុំ (\(270^\circ\)) ៖ \(L = \dfrac{3}{4} \times (2 \times \dfrac{22}{7} \times 14) = \dfrac{3}{4} \times 88 = 66\ \text{cm}\)', 'រង្វង់', 'pisa', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9534, 'នំប៉ីហ្សា (Pizza) មូលមួយត្រូវបានកាត់ជា ៨ ចំណែកស្មើៗគ្នា។ តើមុំផ្ចិតនៃចំណែកនីមួយៗស្មើនឹងប៉ុន្មានដឺក្រេ?', NULL, '["\\(30^\\circ\\)", "\\(45^\\circ\\)", "\\(60^\\circ\\)", "\\(40^\\circ\\)"]', 1, NULL, 3, 'mcq', '\(\dfrac{360^\circ}{8} = 45^\circ\)', 'រង្វង់', 'pisa', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9535, 'ផ្លូវរត់ពហុកីឡដ្ឋានមួយជុំរាងជារង្វង់មានកាំ \(50\ \text{m}\)។ កីឡាករម្នាក់រត់បាន ៥ ជុំ។ គណនាចម្ងាយសរុបដែលគាត់រត់បាន (យក \(\pi pprox 3.14\))។', NULL, '["\\(1\\,570\\ \\text{m}\\)", "\\(314\\ \\text{m}\\)", "\\(3\\,140\\ \\text{m}\\)", "\\(785\\ \\text{m}\\)"]', 0, NULL, 3, 'mcq', 'មួយជុំ ៖ \(P = 2 \times 3.14 \times 50 = 314\ \text{m} \Rightarrow 5\ \text{ជុំ} = 314 \times 5 = 1\,570\ \text{m}\)', 'រង្វង់', 'pisa', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9536, 'កន្ត្រកវិល (Ferris Wheel) មួយមានកាំ \(21\ \text{m}\) និងវិលបានមួយជុំក្នុងរយៈពេល \(2\ \text{នាទី}\)។ គណនាចម្ងាយដែលកៅអីមួយចរបានក្នុងមួយជុំ (យក \(\pi pprox \dfrac{22}{7}\))។', NULL, '["\\(66\\ \\text{m}\\)", "\\(132\\ \\text{m}\\)", "\\(88\\ \\text{m}\\)", "\\(264\\ \\text{m}\\)"]', 1, NULL, 3, 'mcq', '\(P = 2 \times \dfrac{22}{7} \times 21 = 132\ \text{m}\)', 'រង្វង់', 'pisa', 1, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9537, 'គេឱ្យរង្វង់ \(\mathcal{C}(O, r)\) ដែលមានមុំផ្ចិត \(ngle AOB = 60^\circ\) និងកាំ \(r = 6\ \text{cm}\)។
ក. រកប្រវែងរង្វាស់ដឺក្រេនៃធ្នូស្កាត់ \(\overset{rown}{AB}\)។
ខ. សរសេររូបមន្ត និងគណនាប្រវែងធ្នូ \(AB\) ជាសង់ទីម៉ែត្រ (យក \(\pi pprox 3.14\))។', 'g8-455a9ef3f6.svg', '[]', 0, NULL, 5, 'writing', 'ក. រង្វាស់ដឺក្រេនៃធ្នូស្មើនឹងរង្វាស់មុំផ្ចិត ៖ \(\overset{rown}{AB} = ngle AOB = 60^\circ\) (2 ពិន្ទុ)
ខ. រូបមន្តប្រវែងធ្នូ ៖ \(L = \dfrac{2\pi r \times n^\circ}{360^\circ}\) (1 ពិន្ទុ)
ជំនួសតម្លៃ ៖ \(L = \dfrac{2 \times 3.14 \times 6 \times 60}{360} = \dfrac{37.68}{6} = 6.28\ \text{cm}\) (2 ពិន្ទុ)', 'រង្វង់', 'easy', 0, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9538, 'ក្នុងរង្វង់ \(\mathcal{C}(O, r)\) ត្រីកោណ \(OAB\) មានកំពូល \(O\) ជាផ្ចិតរង្វង់ និង \(ngle OAB = 35^\circ\)។
ក. បង្ហាញថា \(\Delta OAB\) ជាត្រីកោណសមបាត រួចទាញរកមុំ \(ngle OBA\)។
ខ. គណនាមុំផ្ចិត \(ngle AOB\) និងទាញរកប្រវែងដឺក្រេនៃធ្នូ \(\overset{rown}{AB}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ដោយ \(OA = OB = r\) (កាំរង្វង់តែមួយ) នោះ \(\Delta OAB\) ជាត្រីកោណសមបាតកំពូល \(O\) នាំឱ្យ \(ngle OBA = ngle OAB = 35^\circ\) (2 ពិន្ទុ)
ខ. ផលបូកមុំក្នុងត្រីកោណ ៖ \(ngle AOB = 180^\circ - (35^\circ + 35^\circ) = 110^\circ\) (2 ពិន្ទុ)
រង្វាស់ធ្នូស្កាត់ ៖ \(\overset{rown}{AB} = ngle AOB = 110^\circ\) (1 ពិន្ទុ)', 'រង្វង់', 'medium', 0, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9539, 'រង្វង់ផ្ចិត \(O\) មានកាំ \(r = 10\ \text{cm}\)។ អង្កត់ផ្ចិត \(CD\) កាត់កែងនឹងអង្កត់ធ្នូ \(AB\) ត្រង់ចំណុច \(H\)។ ដឹងថា \(OH = 6\ \text{cm}\)។
ក. បង្ហាញថា \(H\) ជាចំណុចកណ្តាលនៃ \(AB\)។
ខ. គណនាប្រវែង \(AH\) និងប្រវែងអង្កត់ធ្នូ \(AB\)។', 'g8-77edf0b3c0.svg', '[]', 0, NULL, 5, 'writing', 'ក. អង្កត់ផ្ចិតកែងនឹងអង្កត់ធ្នូ តែងចែកអង្កត់ធ្នូនោះជាពីរស្មើគ្នា នាំឱ្យ \(H\) ជាចំណុចកណ្តាលនៃ \(AB\) (\(AH = HB\)) (2 ពិន្ទុ)
ខ. ក្នុងត្រីកោណកែង \(OHA\) ៖ \(AH = \sqrt{OA^2 - OH^2} = \sqrt{10^2 - 6^2} = \sqrt{64} = 8\ \text{cm}\) (2 ពិន្ទុ)
ប្រវែងអង្កត់ធ្នូ ៖ \(AB = 2AH = 2 \times 8 = 16\ \text{cm}\) (1 ពិន្ទុ)', 'រង្វង់', 'medium', 0, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9540, 'ក្នុងរង្វង់ផ្ចិត \(O\) គេមានធ្នូពីរស្មើគ្នា \(\overset{rown}{AB} = \overset{rown}{CD}\)។
ក. ប្រៀបធៀបមុំផ្ចិត \(ngle AOB\) និង \(ngle COD\)។
ខ. បង្ហាញថាត្រីកោណ \(\Delta AOB \cong \Delta COD\) រួចទាញបញ្ជាក់ថាអង្កត់ធ្នូ \(AB = CD\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ដោយ \(\overset{rown}{AB} = \overset{rown}{CD}\) នាំឱ្យមុំផ្ចិតស្កាត់ធ្នូទាំងពីរប៉ុនគ្នា ៖ \(ngle AOB = ngle COD\) (2 ពិន្ទុ)
ខ. ពិនិត្យ \(\Delta AOB\) និង \(\Delta COD\) មាន \(OA = OC = r, OB = OD = r\) និង \(ngle AOB = ngle COD\) (1 ពិន្ទុ)
ដូចនេះ \(\Delta AOB \cong \Delta COD\) (ករណី ជ-ម-ជ) នាំឱ្យវិបាក \(AB = CD\) (2 ពិន្ទុ)', 'រង្វង់', 'medium', 0, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9541, 'ពីចំណុច \(M\) នៅក្រៅរង្វង់ \(\mathcal{C}(O, 5\ \text{cm})\) គេគូសបន្ទាត់ប៉ះ \(MA\) ត្រង់ \(A\)។ ដឹងថា \(OM = 13\ \text{cm}\)។
ក. បញ្ជាក់ពីលក្ខណៈកែងគ្នារវាងបន្ទាត់ប៉ះ \(MA\) និងកាំ \(OA\)។
ខ. គណនាប្រវែងបន្ទាត់ប៉ះ \(MA\)។
គ. បើគូសបន្ទាត់ប៉ះ \(MB\) មួយទៀតត្រង់ \(B\) តើ \(MB\) មានប្រវែងប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បន្ទាត់ប៉ះរង្វង់កែងនឹងកាំត្រង់ចំណុចប៉ះ នាំឱ្យ \(MA \perp OA\) (មុំ \(ngle OAM = 90^\circ\)) (1 ពិន្ទុ)
ខ. ក្នុងត្រីកោណកែង \(OAM\) ៖ \(MA = \sqrt{OM^2 - OA^2} = \sqrt{13^2 - 5^2} = \sqrt{144} = 12\ \text{cm}\) (2 ពិន្ទុ)
គ. អង្កត់ប៉ះទាំងពីរគូសចេញពីចំណុចតែមួយមានប្រវែងស្មើគ្នា ៖ \(MB = MA = 12\ \text{cm}\) (2 ពិន្ទុ)', 'រង្វង់', 'medium', 0, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9542, 'គេឱ្យរង្វង់ផ្ចិត \(O\) ដែលមានចម្ងាយពីផ្ចិតទៅអង្កត់ធ្នូទាំងពីរ \(AB\) និង \(CD\) ស្មើគ្នា (\(OQ = OR\))។ ដឹងថា \(AB = 6x + 14\) និង \(CD = -4x + 44\)។
ក. ពន្យល់ហេតុអ្វីបានជាអង្កត់ធ្នូ \(AB = CD\)។
ខ. ដោះស្រាយសមីការរកតម្លៃ \(x\)។
គ. គណនាប្រវែងពិតប្រាកដនៃអង្កត់ធ្នូ \(AB\) និង \(CD\)។', 'g8-5679fc37ca.svg', '[]', 0, NULL, 5, 'writing', 'ក. អង្កត់ធ្នូទាំងពីរនៅស្មើចម្ងាយពីផ្ចិតរង្វង់ (\(OQ = OR\)) នាំឱ្យអង្កត់ធ្នូទាំងពីរប៉ុនគ្នា \(AB = CD\) (1 ពិន្ទុ)
ខ. សមីការ ៖ \(6x + 14 = -4x + 44 \Rightarrow 10x = 30 \Rightarrow x = 3\) (2 ពិន្ទុ)
គ. ប្រវែងអង្កត់ធ្នូ ៖ \(AB = 6(3) + 14 = 32\); \(CD = -4(3) + 44 = 32\) (ដូចនេះ \(AB = CD = 32\)) (2 ពិន្ទុ)', 'រង្វង់', 'hard', 0, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9543, 'គេឱ្យរង្វង់ផ្ចិត \(O\) និងអង្កត់ផ្ចិត \(AD\)។ អង្កត់ធ្នូពីរស្របគ្នាគឺ \(AB \parallel CD\)។
ក. បង្ហាញថា \(ngle OAB = ngle ODC\) រួចទាញបញ្ជាក់ថា \(ngle AOB = ngle COD\)។
ខ. បង្ហាញថា \(\Delta OAB \cong \Delta OCD\)។
គ. ទាញសន្និដ្ឋានថា \(AB = CD\) និង \(\overset{rown}{AB} = \overset{rown}{CD}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ដោយ \(AB \parallel CD\) កាត់ដោយ \(AD\) នោះ \(ngle OAB = ngle ODC\) (មុំឆ្លាស់ក្នុង)។ ត្រីកោណ \(OAB\) និង \(OCD\) សមបាតកំពូល \(O\) នាំឱ្យ \(ngle AOB = ngle COD\) (2 ពិន្ទុ)
ខ. \(\Delta OAB\) និង \(\Delta OCD\) មាន \(OA = OD = r, OB = OC = r\) និង \(ngle AOB = ngle COD \Rightarrow \Delta OAB \cong \Delta OCD\) (ជ-ម-ជ) (2 ពិន្ទុ)
គ. វិបាក ៖ \(AB = CD\) និងធ្នូស្កាត់ដោយមុំផ្ចិតស្មើគ្នានាំឱ្យ \(\overset{rown}{AB} = \overset{rown}{CD}\) (1 ពិន្ទុ)', 'រង្វង់', 'hard', 0, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9544, 'នៅលើរង្វង់ \(\mathcal{C}(O, r)\) គេមានចំណុច \(A, B, C, D\) តម្រៀបតាមលំដាប់។ ដឹងថាអង្កត់ធ្នូ \(AB = CD\)។
ក. បង្ហាញថាធ្នូ \(\overset{rown}{AB} = \overset{rown}{CD}\)។
ខ. បង្ហាញថាធ្នូ \(\overset{rown}{AC} = \overset{rown}{BD}\) ដោយប្រើធ្នូរួម \(\overset{rown}{BC}\)។
គ. ទាញបញ្ជាក់ថាអង្កត់ធ្នូ \(AC = BD\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ក្នុងរង្វង់មួយ អង្កត់ធ្នូប៉ុនគ្នានាំឱ្យធ្នូដែលសន្ធឹងក្រោមអង្កត់ធ្នូទាំងពីរប៉ុនគ្នា ៖ \(\overset{rown}{AB} = \overset{rown}{CD}\) (1 ពិន្ទុ)
ខ. ធ្នូ \(\overset{rown}{AC} = \overset{rown}{AB} + \overset{rown}{BC}\) និង \(\overset{rown}{BD} = \overset{rown}{BC} + \overset{rown}{CD}\)។ ដោយ \(\overset{rown}{AB} = \overset{rown}{CD}\) នាំឱ្យ \(\overset{rown}{AC} = \overset{rown}{BD}\) (2 ពិន្ទុ)
គ. ធ្នូប៉ុនគ្នា \(\overset{rown}{AC} = \overset{rown}{BD} \Rightarrow\) អង្កត់ធ្នូ \(AC = BD\) (2 ពិន្ទុ)', 'រង្វង់', 'hard', 0, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9545, 'រង្វង់ផ្ចិត \(O\) មានកាំ \(r = 15\ \text{cm}\)។ អង្កត់ធ្នូពីរស្របគ្នា \(AB = 24\ \text{cm}\) និង \(CD = 18\ \text{cm}\) ស្ថិតនៅសងខាងនៃផ្ចិត \(O\)។
ក. គណនាចម្ងាយ \(d_1\) ពីផ្ចិត \(O\) ទៅអង្កត់ធ្នូ \(AB\)។
ខ. គណនាចម្ងាយ \(d_2\) ពីផ្ចិត \(O\) ទៅអង្កត់ធ្នូ \(CD\)។
គ. គណនាចម្ងាយរវាងអង្កត់ធ្នូទាំងពីរ \(AB\) និង \(CD\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(AH = \dfrac{24}{2} = 12\ \text{cm} \Rightarrow d_1 = \sqrt{15^2 - 12^2} = \sqrt{225 - 144} = 9\ \text{cm}\) (2 ពិន្ទុ)
ខ. \(CK = \dfrac{18}{2} = 9\ \text{cm} \Rightarrow d_2 = \sqrt{15^2 - 9^2} = \sqrt{225 - 81} = 12\ \text{cm}\) (2 ពិន្ទុ)
គ. ចម្ងាយរវាងអង្កត់ធ្នូទាំងពីរ (សងខាងផ្ចិត) ៖ \(d = d_1 + d_2 = 9 + 12 = 21\ \text{cm}\) (1 ពិន្ទុ)', 'រង្វង់', 'hard', 0, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9546, 'កង់កង់ប្រណាំងមួយមានកាំ \(r = 35\ \text{cm}\)។
ក. គណនាបរិមាត្រនៃកង់កង់គិតជាម៉ែត្រ (យក \(\pi pprox \dfrac{22}{7}\))។
ខ. បើសិស្សម្នាក់ជិះកង់នោះបាន ៥០០ ជុំ តើគាត់ធ្វើដំណើរបានចម្ងាយប៉ុន្មានម៉ែត្រ?
គ. បើគាត់ត្រូវជិះចម្ងាយ \(4.4\ \text{km}\) តើកង់ត្រូវវិលប៉ុន្មានជុំ?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បរិមាត្រកង់ ៖ \(P = 2\pi r = 2 \times \dfrac{22}{7} \times 35 = 220\ \text{cm} = 2.2\ \text{m}\) (2 ពិន្ទុ)
ខ. ចម្ងាយធ្វើដំណើរ ៥០០ ជុំ ៖ \(2.2 \times 500 = 1\,100\ \text{m}\) (1 ពិន្ទុ)
គ. ចំនួនជុំសម្រាប់ \(4.4\ \text{km} = 4\,400\ \text{m}\) ៖ \(N = \dfrac{4\,400}{2.2} = 2\,000\ \text{ជុំ}\) (2 ពិន្ទុ)', 'រង្វង់', 'pisa', 0, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9547, 'នាឡិកាជញ្ជាំងមូលមួយមានកាំ \(r = 21\ \text{cm}\)។ មុខនាឡិកាត្រូវបានបែងចែកជា ១២ ម៉ោងស្មើៗគ្នា។
ក. គណនាមុំផ្ចិតដែលបង្កើតឡើងដោយចន្លោះម៉ោងនីមួយៗ (១ ម៉ោង)។
ខ. នៅម៉ោង ៤:០០ គត់ តើមុំផ្ចិតតូចរវាងទ្រនិចម៉ោងនិងទ្រនិចនាទីស្មើនឹងប៉ុន្មានដឺក្រេ?
គ. គណនាប្រវែងធ្នូតូចនៅលើគែមនាឡិកាដែលស្កាត់ដោយមុំនៅម៉ោង ៤:០០ (យក \(\pi pprox \dfrac{22}{7}\))។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មុំចន្លោះ ១ ម៉ោង ៖ \(\dfrac{360^\circ}{12} = 30^\circ\) (1 ពិន្ទុ)
ខ. នៅម៉ោង ៤:០០ គត់ មាន ៤ ចន្លោះ ៖ \(lpha = 4 \times 30^\circ = 120^\circ\) (2 ពិន្ទុ)
គ. ប្រវែងធ្នូស្កាត់ ៖ \(L = \dfrac{2 \times \frac{22}{7} \times 21 \times 120}{360} = \dfrac{132 \times 1}{3} = 44\ \text{cm}\) (2 ពិន្ទុ)', 'រង្វង់', 'pisa', 0, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9548, 'នំប៉ីហ្សាមូលធំមួយមានអង្កត់ផ្ចិត \(40\ \text{cm}\) ត្រូវបានកាត់ជា ៨ ចំណែកស្មើៗគ្នាសម្រាប់មនុស្ស ៨ នាក់។
ក. គណនាកាំ \(r\) និងមុំផ្ចិតនៃចំណែកនីមួយៗ។
ខ. គណនាផ្ទៃក្រឡានៃនំប៉ីហ្សាទាំងមូល (យក \(\pi pprox 3.14\))។
គ. គណនាផ្ទៃក្រឡានៃនំប៉ីហ្សាមួយចំណែកដែលមនុស្សម្នាក់ទទួលបាន។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. កាំ \(r = \dfrac{40}{2} = 20\ \text{cm}\); មុំផ្ចិត ៖ \(\dfrac{360^\circ}{8} = 45^\circ\) (2 ពិន្ទុ)
ខ. ផ្ទៃសរុប ៖ \(S = \pi r^2 = 3.14 \times 20^2 = 3.14 \times 400 = 1\,256\ \text{cm}^2\) (2 ពិន្ទុ)
គ. ផ្ទៃមួយចំណែក ៖ \(S_1 = \dfrac{1\,256}{8} = 157\ \text{cm}^2\) (1 ពិន្ទុ)', 'រង្វង់', 'pisa', 0, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9549, 'ផ្លូវរត់ប្រណាំងរាងជារង្វង់មួយមានកាំខាងក្នុង \(r_1 = 30\ \text{m}\) និងកាំខាងក្រៅ \(r_2 = 35\ \text{m}\)។
ក. គណនាប្រវែងមួយជុំនៃគន្លងខាងក្នុង (យក \(\pi pprox 3.14\))។
ខ. គណនាប្រវែងមួយជុំនៃគន្លងខាងក្រៅ។
គ. បើកីឡាករពីរនាក់រត់មួយជុំ តើអ្នករត់គន្លងក្រៅរត់ឆ្ងាយជាងអ្នករត់គន្លងក្នុងប៉ុន្មានម៉ែត្រ?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. គន្លងក្នុង ៖ \(P_1 = 2 \times 3.14 \times 30 = 188.4\ \text{m}\) (2 ពិន្ទុ)
ខ. គន្លងក្រៅ ៖ \(P_2 = 2 \times 3.14 \times 35 = 219.8\ \text{m}\) (2 ពិន្ទុ)
គ. ចម្ងាយខុសគ្នា ៖ \(219.8 - 188.4 = 31.4\ \text{m}\) (1 ពិន្ទុ)', 'រង្វង់', 'pisa', 0, '8', 'រង្វង់', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9550, 'តុបាយមូលមួយមានអង្កត់ផ្ចិត \(1.4\ \text{m}\)។ គេចង់កាត់កញ្ចក់មូលមួយផ្ទាំងដាក់ពីលើឱ្យល្មមស្មើនឹងមាត់តុ។
ក. គណនាកាំ និងផ្ទៃក្រឡានៃកញ្ចក់មូលនោះ (យក \(\pi pprox \dfrac{22}{7}\))។
ខ. គេចង់ដេរកម្រាលតុក្រណាត់ដែលមានគែមធ្លាក់ចុះ \(0.2\ \text{m}\) ជុំវិញមាត់តុ។ រកអង្កត់ផ្ចិតនៃកម្រាលតុក្រណាត់។
គ. គណនាផ្ទៃក្រឡានៃកម្រាលតុក្រណាត់នោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. កាំ \(r = 0.7\ \text{m}\); ផ្ទៃកញ្ចក់ ៖ \(S = \dfrac{22}{7} \times 0.7^2 = \dfrac{22}{7} \times 0.49 = 1.54\ \text{m}^2\) (2 ពិន្ទុ)
ខ. អង្កត់ផ្ចិតកម្រាលក្រណាត់ ៖ \(D = 1.4 + 2(0.2) = 1.8\ \text{m} \Rightarrow R = 0.9\ \text{m}\) (1 ពិន្ទុ)
គ. ផ្ទៃកម្រាលក្រណាត់ ៖ \(S_{\text{ក្រណាត់}} = 3.14 \times 0.9^2 = 3.14 \times 0.81 pprox 2.54\ \text{m}^2\) (2 ពិន្ទុ)', 'រង្វង់', 'pisa', 0, '8', 'រង្វង់', NULL, 0);
